create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,created_at timestamptz default now());
create table if not exists businesses(id uuid primary key default gen_random_uuid(),owner_id uuid not null unique references auth.users(id) on delete cascade,name text not null,created_at timestamptz default now());
create table if not exists leads(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,name text not null,phone text,email text,source text not null default 'Other',status text not null default 'new' check(status in ('new','contacted','interested','follow-up','won','lost')),estimated_value numeric,next_follow_up date,notes text,created_at timestamptz default now());
alter table profiles enable row level security;alter table businesses enable row level security;alter table leads enable row level security;
drop policy if exists profiles_self on profiles;create policy profiles_self on profiles for all using(id=auth.uid()) with check(id=auth.uid());
drop policy if exists businesses_owner on businesses;create policy businesses_owner on businesses for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
drop policy if exists leads_owner on leads;create policy leads_owner on leads for all using(exists(select 1 from businesses b where b.id=leads.business_id and b.owner_id=auth.uid())) with check(exists(select 1 from businesses b where b.id=leads.business_id and b.owner_id=auth.uid()));
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,new.raw_user_meta_data->>'full_name') on conflict(id) do update set full_name=excluded.full_name; insert into public.businesses(owner_id,name) values(new.id,coalesce(new.raw_user_meta_data->>'business_name','My Business')) on conflict(owner_id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create index if not exists leads_business_created_idx on leads(business_id,created_at desc);create index if not exists leads_followup_idx on leads(business_id,next_follow_up);